(function () {
'use strict';
var header = document.getElementById('siteHeader');
var backTop = document.getElementById('backTop');
function onScroll() {
if (header) header.classList.toggle('scrolled', window.scrollY > 10);
if (backTop) backTop.classList.toggle('show', window.scrollY > 560);
}
window.addEventListener('scroll', onScroll, { passive: true });
onScroll();
if (backTop) {
backTop.addEventListener('click', function () {
window.scrollTo({ top: 0, behavior: 'smooth' });
});
}
var navToggle = document.getElementById('navToggle');
var siteNav = document.getElementById('siteNav');
function closeNav() {
if (!siteNav) return;
siteNav.classList.remove('open');
if (navToggle) {
navToggle.classList.remove('open');
navToggle.setAttribute('aria-expanded', 'false');
}
document.body.classList.remove('no-scroll');
}
if (navToggle && siteNav) {
navToggle.addEventListener('click', function () {
var open = siteNav.classList.toggle('open');
navToggle.classList.toggle('open', open);
navToggle.setAttribute('aria-expanded', open ? 'true' : 'false');
document.body.classList.toggle('no-scroll', open);
});
siteNav.querySelectorAll('a').forEach(function (a) {
a.addEventListener('click', closeNav);
});
}
var revealEls = document.querySelectorAll('.reveal');
if ('IntersectionObserver' in window && revealEls.length) {
var io = new IntersectionObserver(function (entries) {
entries.forEach(function (entry) {
if (entry.isIntersecting) {
entry.target.classList.add('in');
io.unobserve(entry.target);
}
});
}, { threshold: 0.12, rootMargin: '0px 0px -40px 0px' });
revealEls.forEach(function (el) { io.observe(el); });
} else {
revealEls.forEach(function (el) { el.classList.add('in'); });
}
var counters = document.querySelectorAll('[data-count]');
if (counters.length) {
var cio = new IntersectionObserver(function (entries) {
entries.forEach(function (entry) {
if (!entry.isIntersecting) return;
var el = entry.target;
var target = parseFloat(el.getAttribute('data-count'));
var suffix = el.getAttribute('data-suffix') || '';
var dur = 1600, start = null;
function step(ts) {
if (!start) start = ts;
var p = Math.min((ts - start) / dur, 1);
var eased = 1 - Math.pow(1 - p, 3);
var val = Math.round(target * eased);
el.textContent = val.toLocaleString('en-US') + suffix;
if (p < 1) requestAnimationFrame(step);
}
requestAnimationFrame(step);
cio.unobserve(el);
});
}, { threshold: 0.5 });
counters.forEach(function (el) { cio.observe(el); });
}
var filterBar = document.getElementById('filterBar');
if (filterBar) {
var cards = document.querySelectorAll('.pcard-wrap');
filterBar.addEventListener('click', function (e) {
var btn = e.target.closest('.filter-btn');
if (!btn) return;
filterBar.querySelectorAll('.filter-btn').forEach(function (b) { b.classList.remove('is-active'); });
btn.classList.add('is-active');
var f = btn.getAttribute('data-filter');
cards.forEach(function (card) {
var match = f === 'all' || card.getAttribute('data-cat') === f;
card.classList.toggle('hide', !match);
});
});
}
var cnButtons = document.querySelectorAll('[data-lang-cn]');
if (cnButtons.length) {
var toastTimer = null;
cnButtons.forEach(function (btn) {
btn.addEventListener('click', function () {
var toast = document.getElementById('toast');
if (!toast) return;
toast.classList.add('show');
clearTimeout(toastTimer);
toastTimer = setTimeout(function () { toast.classList.remove('show'); }, 3200);
});
});
}
function initForm(formId, opts) {
var form = document.getElementById(formId);
if (!form) return;
var successBox = document.getElementById(opts.successId);
var btnText = opts.btnText || 'Send Message';
var submitBtn = form.querySelector('button[type="submit"]');
function setFieldState(field, errorMsg, valid) {
var group = field.closest('.form-group');
var err = group ? group.querySelector('.error-msg') : null;
if (valid) {
field.classList.remove('is-invalid');
if (err) err.classList.remove('show');
return true;
}
field.classList.add('is-invalid');
if (err) {
err.textContent = errorMsg || 'This field is required.';
err.classList.add('show');
}
return false;
}
function validate() {
var ok = true;
form.querySelectorAll('[data-required]').forEach(function (field) {
var val = field.value.trim();
var valid = true, msg = 'This field is required.';
if (field.type === 'checkbox' || field.type === 'radio') {
valid = field.checked;
} else if (field.tagName === 'SELECT') {
valid = val !== '';
} else if (!val) {
valid = false;
} else if (field.type === 'email' && !/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(val)) {
valid = false;
msg = 'Please enter a valid email address.';
} else if (field.type === 'tel' && val.length < 6) {
valid = false;
msg = 'Please enter a valid phone number.';
}
if (!setFieldState(field, msg, valid)) ok = false;
});
return ok;
}
form.querySelectorAll('.form-control').forEach(function (field) {
field.addEventListener('input', function () { setFieldState(field, null, true); });
field.addEventListener('change', function () { setFieldState(field, null, true); });
});
form.addEventListener('submit', function (e) {
e.preventDefault();
if (!validate()) {
var firstInvalid = form.querySelector('.is-invalid');
if (firstInvalid) firstInvalid.focus();
return;
}
if (submitBtn) {
submitBtn.disabled = true;
submitBtn.textContent = 'Sending...';
}
setTimeout(function () {
form.style.display = 'none';
if (successBox) successBox.classList.add('show');
if (submitBtn) { submitBtn.disabled = false; submitBtn.textContent = btnText; }
}, 900);
});
}
initForm('contactForm', { successId: 'contactSuccess' });
initForm('quoteForm', { successId: 'quoteSuccess' });
initForm('newsletterForm', { successId: 'nlSuccess', btnText: 'Subscribe' });
var yearEl = document.getElementById('year');
if (yearEl) yearEl.textContent = new Date().getFullYear();
})();
